// Build Outer Heaven report message
const body = $json.body || $json;

const reportId = body.reportId || body.id || `oh_${Date.now()}`;
const title = body.title || body.subject || 'Outer Heaven Report';
const status = body.status || 'info';
const content = body.content || body.message || body.report || '';
const source = body.source || 'outer-heaven';
const severity = body.severity || body.level || 'normal';

const emoji = {
  critical: '🚨',
  high: '⚠️',
  normal: '📊',
  low: 'ℹ️',
  info: '📊'
}[severity] || '📊';

const text = [
  `${emoji} OUTER HEAVEN REPORT`,
  ``,
  `Title: ${title}`,
  `Status: ${status}`,
  `Severity: ${severity}`,
  `Source: ${source}`,
  content ? `\nDetails:\n${content}` : '',
  ``,
  `ID: ${reportId}`,
  `Time: ${new Date().toISOString()}`
].filter(Boolean).join('\n');

return [{ json: { text, reportId, title, severity } }];

// Preflight: verify TELEGRAM_BOT_TOKEN is configured
const token = $env.TELEGRAM_BOT_TOKEN;
if (!token || token === '' || token === 'undefined' || token === 'null') {
  return [{
    json: {
      sent: false,
      error: 'TELEGRAM_BOT_TOKEN is not set or empty. This causes HTTP 404 from Telegram API (the /bot<empty>/sendMessage path does not exist).',
      hint: 'Operator: Set TELEGRAM_BOT_TOKEN in n8n Settings > Variables. Format: 123456789:ABCdefGHI...',
      originalMessage: $json.text
    }
  }];
}

const chatId = $env.HIVE_OUTER_HEAVEN_CHAT_ID || $env.HIVE_TELEGRAM_CHAT_ID;
if (!chatId) {
  return [{
    json: {
      sent: false,
      error: 'HIVE_OUTER_HEAVEN_CHAT_ID (or HIVE_TELEGRAM_CHAT_ID) is not set.',
      hint: 'Operator: Set the chat_id env var in n8n Settings > Variables.',
      originalMessage: $json.text
    }
  }];
}

return [{
  json: {
    ...$json,
    _telegram: { token, chatId, ready: true }
  }
}];
